variadics.rn<pre><code>fun sum(...nums) {
    var ret = 0
    for x in nums {
        ret += x
    }
    return ret
}

sum(1, 2, 3) # Output: 6
sum(1, 2, 3, 4) # Output: 10
sum() # Output: 0
</code></pre>

example.rn<pre><code>import io

fun iseven(num) -&gt; num % 2 == 0

class Greeter {
    fun __constructor__(name) {
        this.name = name
    }

    fun greet() {
        print("Hello, " + this.name)
    }
}

var name = io.Input.get_string("Name: ")
var greeter = Greeter(name)
greeter.greet()
print("Name length: " + str(name.length()))
print("Even test: " + str(iseven(42)))
